function removeFromFirstChild(root) {
  // Get all children of the root element
  const children = Array.from(root.children);

  // Remove the first child and update the DOM
  let lastChild = undefined;
  for(let i = 0; i < children.length; i++) {
    if(lastChild === undefined) {
      // No previous elements for this child
      lastChild = children[i];
      continue;
    }
    if(children[i] !== lastChild) {
      // Move up one position in case the child was pushed down on an old iteration
      lastChild = children.pop();
      children.splice(i+1, 0, ...children); // Replace remaining items
    } else if(lastChild != undefined) {
      lastChild.remove(); // Optionally remove the old child node (this should be removed when done)
    }
  }

  // Return null because we don't want any changes
  return null;
